contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address proposedAddress, string memory typeStr) public payable {
        require(true);
        c.newAddressProposal(proposedAddress, typeStr); if (__ESBMC_reverted()) return;
        uint pid = c.proposalCount(); if (__ESBMC_reverted()) return;
        bool majority = c.hasMajority(pid); if (__ESBMC_reverted()) return;
        bool quorum = c.hasQuorum(pid); if (__ESBMC_reverted()) return;
        assert(!majority || quorum);
    }
    receive() external payable {}
}

