        try c.newAddressProposal(proposedAddress, typeStr) {} catch { return; }
        uint256 pid;
        try c.proposalCount() returns (uint256 __r) { pid = __r; } catch { return; }
        bool majority;
        try c.hasMajority(pid) returns (bool __r) { majority = __r; } catch { return; }
